using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Collections.Generic;using System.Security.Cryptography;using System.Web.Script.Serialization;using VirgilPatch;
class SecurityAdditionsTests {
 static string root;static int passed;static JavaScriptSerializer js=new JavaScriptSerializer();static RSACryptoServiceProvider key;
 static byte[] B(string s){return Encoding.UTF8.GetBytes(s);}static void Assert(bool b,string why){if(!b)throw new Exception(why);}static void Reject(Action a){try{a();}catch(Exception){return;}throw new Exception("Expected rejection");}static void Test(string n,Action a){a();passed++;Console.WriteLine("PASS "+n);}
 static State Fresh(){string area=Path.Combine(root,Guid.NewGuid().ToString("N"));Config.StateDir=Path.Combine(area,"state");var s=new State{patches_dir=Path.Combine(area,"Patches")};Directory.CreateDirectory(s.patches_dir);return s;}
 static RepairSource Source(){var s=new RepairSource();s.Publish(new Dictionary<string,Dictionary<string,byte[]>>{{"Test",new Dictionary<string,byte[]>{{"a.ogg",B("content")}}}});return s;}
 static byte[] Release(){long size=8192;string hash=new string('a',64),v="1.5.7.0";string sig=Convert.ToBase64String(key.SignData(ProgramRelease.SigningBytes(v,size,hash),CryptoConfig.MapNameToOID("SHA256")));return B(js.Serialize(new{format=1,version=v,file=ProgramRelease.BinaryPath,size=size,sha256=hash,signature=sig}));}
 static void Parse(byte[] b){ProgramRelease.Parse(b,key.ToXmlString(false));}
 static int Main(string[] a){try{root=Path.GetFullPath(a[0]);Directory.CreateDirectory(root);key=new RSACryptoServiceProvider(new CspParameters(24));key.PersistKeyInCsp=false;key.FromXmlString(File.ReadAllText("E:/Workspaces/Codex/VirgilPatchVersioning_20261020/test-results/self-update-fixture/test-key.xml"));
 Test("canonical-signed-release-and-utf8-bom-remain-supported",delegate{var b=Release();Parse(b);Parse(new byte[]{239,187,191}.Concat(b).ToArray());});
 Test("duplicate-signed-release-version-is-rejected",delegate{var x=Encoding.UTF8.GetString(Release());Reject(()=>Parse(B("{\"version\":\"9.9.9.9\","+x.Substring(1))));});
 Test("escaped-duplicate-signed-release-field-is-rejected",delegate{var x=Encoding.UTF8.GetString(Release());Reject(()=>Parse(B("{\"\\u0076ersion\":\"1.5.7.0\","+x.Substring(1))));});
 Test("invalid-utf8-release-is-rejected",delegate{Reject(()=>Parse(new byte[]{123,34,118,34,58,34,255,34,125}));});
 Test("missing-release-fields-fail-closed",delegate{var d=js.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(Release()));d.Remove("size");d["other"]=8192;Reject(()=>Parse(B(js.Serialize(d))));});
 Test("only-immutable-canonical-git-commits-are-accepted",delegate{foreach(var c in new[]{"main","../main",new string('a',40)+"\n",new string('A',40),"a/b"})Reject(()=>GitHubSource.RawUrl(c,"index.json"));Assert(GitHubSource.RawUrl(new string('a',40),"index.json").Contains(new string('a',40)),"Valid commit rejected");});
 Test("raw-download-paths-reject-traversal-ads-and-empty-components",delegate{foreach(var p in new[]{"../index.json","patches//bad.blp",".git/config","x.blp:ads","/index.json"})Reject(()=>GitHubSource.RawUrl(new string('a',40),p));});
 Test("all-six-superscript-windows-device-names-blocked",delegate{foreach(var digit in new[]{'\u00b9','\u00b2','\u00b3'})foreach(var prefix in new[]{"COM","LPT"}){string n=prefix+digit;Reject(()=>Safety.Asset(n+".skin",false));Reject(()=>Safety.Relative("safe/"+n+"/a.blp"));}});
 Test("ordinary-device-like-asset-names-remain-valid",delegate{foreach(var n in new[]{"COM10.skin","LPT10.blp","comic.m2","safe/combat.ogg"})Safety.Asset(n,false);});
 Test("valid-saved-state-and-counters-roundtrip",delegate{var s=Fresh();s.folder_check_uses=4;s.installed["Test/a.ogg"]=new string('a',40);s.Save();var loaded=State.Load();Assert(loaded.patches_dir==s.patches_dir&&loaded.folder_check_uses==4&&loaded.installed["Test/a.ogg"]==new string('a',40),"State compatibility lost");});
 Test("ambiguous-saved-state-is-not-used",delegate{var s=Fresh();s.Save();var file=Path.Combine(Config.StateDir,"state.json");string text=File.ReadAllText(file);File.WriteAllText(file,"{\"patches_dir\":\"malicious\","+text.Substring(1));Assert(State.Load().patches_dir==null,"Duplicate root accepted");Assert(!Directory.EnumerateFileSystemEntries(s.patches_dir).Any(),"State load changed game");});
 Test("unsafe-saved-removal-keys-and-invalid-hashes-discarded",delegate{var s=Fresh();s.installed["Test/a.ogg"]=new string('a',40);s.installed["../outside.blp"]=new string('a',40);s.installed["Test/b.ogg"]="not-a-hash";s.Save();var loaded=State.Load();Assert(loaded.installed.Count==1&&loaded.installed.ContainsKey("Test/a.ogg"),"Unsafe tracking entries retained");});
 Test("simultaneous-patch-writer-blocked-before-download-or-rename",delegate{var s=Fresh();var src=Source();var u=new Updater(src,s);var plan=u.Check();using(var locked=Updater.AcquirePatchLock(s.patches_dir)){Reject(()=>u.Apply(plan,CancellationToken.None));Assert(src.Downloads.Count==0&&!File.Exists(Path.Combine(s.patches_dir,"Test/patch.json")),"Concurrent writer touched patch");}u.Apply(plan,CancellationToken.None);Assert(File.Exists(Path.Combine(s.patches_dir,"Test/patch.json")),"Retry after unlock failed");Assert(!File.Exists(Path.Combine(s.patches_dir,".virgil-update.lock")),"Lock marker left behind");});
 Test("failed-update-releases-lock-and-retains-retry",delegate{var s=Fresh();var src=Source();src.FailAll=true;var u=new Updater(src,s);Reject(()=>u.Apply(u.Check(),CancellationToken.None));using(var locked=Updater.AcquirePatchLock(s.patches_dir)){}src.FailAll=false;u.Apply(u.Check(),CancellationToken.None);Assert(File.Exists(Path.Combine(s.patches_dir,"Test/patch.json")),"Failure stranded lock");});
 Test("different-patches-roots-can-be-locked-independently",delegate{var a1=Fresh();var a2=Fresh();using(var l1=Updater.AcquirePatchLock(a1.patches_dir))using(var l2=Updater.AcquirePatchLock(a2.patches_dir))Assert(l1!=null&&l2!=null,"Global lock blocked other installation");});
 key.Dispose();Console.WriteLine("TOTAL "+passed+" additive security cases passed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
